/* 第一章完整材料题库（续）。 */
TS('c1-09','1.5','利用全等三角形测量不可达距离',
 '利用全等三角形的对应边相等，把难以直接测量的距离转移成可直接测量的线段。关键是构造并证明两个三角形全等。',
 '先确定目标距离对应哪条可测线段，再找中点、平行、垂直、对顶角等条件证明全等。',
 '测量结论必须建立在全等证明上，不能只凭示意图判断线段相等。',
 C1('c1-10-1','1.4（材料编号）巩固训练 第1题','证明题','如图，A、B 位于池塘两端，D 为水房，C 是 BD 的中点；A、C、E 共线且 CE=CA。说明为什么量出 ED 就能得到 AB。','AB=DE',['C 是 BD 中点，所以 BC=CD；又 AC=CE。','∠BCA=∠DCE（对顶角）。','△ACB≌△ECD（SAS），所以 AB=DE。'],[],'c1-10-1',{alsoQuestion:true}),
 C1('c1-10-2','1.4（材料编号）巩固训练 第2题','证明题','如图，为测量池塘沿岸 A、E 两点距离，取 AB∥CD 且 AB=CD，E 是 BC 的中点。只测 DE 是否可得到 AE？说明理由。','可以，AE=DE',['AB∥CD，所以相关角相等；E 是 BC 中点，所以 BE=CE。','结合 AB=CD，可证明 △AEB≌△DEC（SAS）。','因此 AE=DE，只需测 DE。'],[],'c1-10-2'),
 C1('c1-10-3','1.4（材料编号）巩固训练 第3题','解答题','如图，用“拐尺”测量透明隔离房间深度。O 为 AB 中点，CA⊥AB，BD⊥AB，CA=BD。说明如何使用工具，并证明测得的 DF 等于房间深度 CE。','使 F、O、E 共线后测 DF；CE=DF',['使 AC 与房间内壁共线且 C 接触端点，人在 BD 延长线上移动到 F，使 F、O、E 共线。','∠A=∠B=90°，AO=BO，且对顶角相等，所以 △BOF≌△AOE（ASA），BF=AE。','又 AC=BD，因此 AE−AC=BF−BD，即 CE=DF。'],[],'c1-10-3')
);

// 1.0 本章专题 --------------------------------------------------------------
TS('c1-10','1.0','专题一：过同一顶点的角平分线与高线模型',
 '同一顶点同时出现角平分线和高时，可把角平分得到的半角与直角三角形中的余角关系结合。',
 '先用内角和求顶角，再用角平分线取一半；高线带来 90°，最后用角的和差或余角求目标角。',
 '注意 F 在角平分线内部或延长线上时，角的方向不同，但平行关系仍可保持目标角大小。',
 C1('c1-11-1','专题一 第1题','解答题','如图，在 △ABC 中，AE 是角平分线，AD 是高，∠C=40°，∠B=70°，DF⊥AE。（1）求 ∠CAE；（2）求 ∠ADF。','（1）35°；（2）75°',['∠A=180°−40°−70°=70°，AE 平分 ∠A，所以 ∠CAE=35°。','AD⊥BC，得 ∠CAD=50°，所以 ∠DAE=15°。','DF⊥AE，所以 ∠ADF=90°−15°=75°。'],[],'c1-11-1',{alsoQuestion:true}),
 C1('c1-11-2','专题一 第2题','解答题','如图，AE 平分 ∠BAC，AD⊥BC。（1）若 ∠C=70°，∠B=30°，求 ∠DAE；（2）F 在 AE 上，FG⊥BC，∠B=40°，∠C=80°，求 ∠EFG；（3）若 F 在 AE 延长线上，∠EFG 是否改变？','（1）20°；（2）20°；（3）不变，仍为20°',['（1）∠A=80°，∠BAE=40°；AD⊥BC 得 ∠BAD=60°，所以 ∠DAE=20°。','（2）AD∥FG，所以 ∠EFG=∠EAD；由 ∠A=60°、∠BAE=30°、∠BAD=50° 得 ∠EAD=20°。','（3）F 移到延长线上后 AD∥FG 仍成立，因此目标角仍为 20°。'],[],'c1-11-2')
);

TS('c1-11','1.0','专题二：平移模型',
 '平移模型中对应线段保持平行、相等，通过线段和差得到第三组等边后，可用 SAS/SSS 证明位置变化前后的三角形仍全等。',
 '先根据共线点位置用加减公共线段得到等长，再用平行线得到等角。',
 '平移后点的位置发生变化，线段和差式要根据当前点的先后顺序重新写。',
 C1('c1-12-1','专题二 跟踪练习 第1题','证明题','如图①，A、B、C、D 在同一直线上，AB=CD，DE∥AF，DE=AF。证明 △AFC≌△DEB；将 △DEB 沿 AD 方向平移到图②③位置后，其余条件不变，判断是否仍全等并证明。','三种位置下均全等',['由 AB=CD，根据各图点的先后位置，可用加（减）公共线段得到 AC=BD。','DE∥AF，所以 ∠A=∠D。','AF=DE，结合 AC=BD、夹角相等，均有 △AFC≌△DEB（SAS）。'],[],'c1-12-1',{alsoQuestion:true})
);

TS('c1-12','1.0','专题二：对称模型',
 '对称模型常具有公共边、公共角或成对相等的角，通过 ASA/SAS 证明对称位置上的三角形全等。',
 '先找公共边和角，再由已知角关系构造第二组三角形全等。',
 '图形看起来对称不等于已经证明全等，仍需列出判定条件。',
 C1('c1-12-2','专题二 跟踪练习 第2题','证明题','如图，在四边形 ACBD 中，P 在对角线 AB 上，连接 PC、PD，已知 ∠1=∠2，∠3=∠4。（1）证明 △BDP≌△BCP；（2）证明 AD=AC。','（1）△BDP≌△BCP；（2）AD=AC',['由补角关系，∠DPB=∠CPB；PB 为公共边，且 ∠3=∠4，所以 △BDP≌△BCP（ASA），得 DP=CP。','在 △ADP 与 △ACP 中，AP 公共、∠1=∠2、DP=CP，所以两三角形全等（SAS），得 AD=AC。'],[],'c1-12-2',{alsoQuestion:true})
);

TS('c1-13','1.0','专题二：旋转模型',
 '旋转模型通过“相等的大角加减公共角”得到夹角相等，再利用两组对应边相等用 SAS 证明全等。',
 '看到共顶点、相等边和相等大角时，优先做角的加减，把条件转成 SAS 的夹角。',
 '旋转过程中两三角形可能无重叠或部分重叠，不能只按图形外观找对应角。',
 C1('c1-12-3','专题二 跟踪练习 第3题','证明题','如图“风筝”中，AB=AD，AC=AE，∠BAE=∠DAC。证明 ∠E=∠C。','∠E=∠C',['由 ∠BAE=∠DAC，加公共角 ∠EAC，得 ∠CAB=∠EAD。','AB=AD，AC=AE，所以 △ABC≌△ADE（SAS）。','对应角相等，∠C=∠E。'],[],'c1-12-3',{alsoQuestion:true}),
 C1('c1-12-4','专题二 跟踪练习 第4题','证明题','如图，在 △ABC 和 △AED 中，AB=AE，∠BAE=∠CAD，AC=AD。证明 △ABC≌△AED。','△ABC≌△AED（SAS）',['由 ∠BAE=∠CAD，加公共角 ∠CAE，得到 ∠BAC=∠EAD。','AB=AE，AC=AD。','两边及夹角对应相等，所以 △ABC≌△AED（SAS）。'],[],'c1-12-4'),
 C1('c1-12-5','专题二 跟踪练习 第5题','解答题','如图，AC⊥BC，DC⊥EC，AC=BC，DC=EC，AE 与 BD 相交于 F。（1）证明 AE=BD；（2）求 ∠AFD。','（1）AE=BD；（2）90°',['由两个直角及公共角的和差，得到 ∠ACE=∠BCD。','AC=BC，CE=CD，所以 △ACE≌△BCD（SAS），得 AE=BD，并得到一组对应角相等。','结合直角三角形余角关系，可得 AE⊥BD，所以 ∠AFD=90°。'],[],'c1-12-5')
);
